// Ported from the Node app's Sequelize model StudentSubject (first generated by tools/gen-efcore.mjs).
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using SchoolERP.Domain.Entities;

namespace SchoolERP.Infrastructure.Persistence.Configurations;

internal sealed class StudentSubjectConfiguration : IEntityTypeConfiguration<StudentSubject>
{
    public void Configure(EntityTypeBuilder<StudentSubject> builder)
    {
        builder.ToTable("student_subjects");
        builder.ConfigureAudit();
        builder.HasQueryFilter(e => !e.Delstatus);
        builder.HasKey(e => e.Id);
        builder.Property(e => e.Id).HasColumnName("id").UseIdentityColumn();
        builder.Property(e => e.StudentId).HasColumnName("student_id");
        builder.Property(e => e.ClassSubjectId).HasColumnName("class_subject_id");
        builder.HasIndex(e => new { e.StudentId, e.ClassSubjectId }).IsUnique().HasDatabaseName("uq_student_subject");
        builder.HasOne(e => e.Student).WithMany(p => p.StudentSubjects).HasForeignKey(e => e.StudentId).OnDelete(DeleteBehavior.NoAction);
        builder.HasOne(e => e.ClassSubject).WithMany(p => p.StudentSubjects).HasForeignKey(e => e.ClassSubjectId).OnDelete(DeleteBehavior.NoAction);
    }
}
